@Composable fun SplashScreen( onNavigate: () -> Unit, viewModel: SplashViewModel = viewModel() ) { var startAnimation by remember { mutableStateOf(false) }
LaunchedEffect(Unit) { startAnimation = true viewModel.startTimer { onNavigate() } }
val scale by animateFloatAsState( targetValue = if (startAnimation) 1.1f else 0.8f, animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy) ) val alpha by animateFloatAsState( targetValue = if (startAnimation) 1f else 0f, animationSpec = tween(1000) )
Box( modifier = Modifier .fillMaxSize() .background( Brush.verticalGradient( colors = listOf(Color(0xFFF4F6F3), Color(0xFFE8F5E9)) ) ), contentAlignment = Alignment.Center ) { Column(horizontalAlignment = Alignment.CenterHorizontally) {
Image( painter = painterResource(id = R.drawable.logo), contentDescription = "App Logo", modifier = Modifier .size(160.dp) .graphicsLayer { scaleX = scale scaleY = scale this.alpha = alpha } )
Spacer(modifier = Modifier.height(24.dp))
AnimatedVisibility( visible = startAnimation, enter = fadeIn(animationSpec = tween(1500)) ) { Column(horizontalAlignment = Alignment.CenterHorizontally) { Text( text = "AgrInsight AI", style = MaterialTheme.typography.headlineMedium, color = Color(0xFF2E7D32), fontWeight = FontWeight.Bold ) Text( text = "PRECISION AGRICULTURE SOLUTIONS", style = MaterialTheme.typography.labelSmall, color = Color.Gray, letterSpacing = 1.sp ) } }
Spacer(modifier = Modifier.height(40.dp))
CircularProgressIndicator( modifier = Modifier.size(35.dp), color = Color(0xFF2E7D32), strokeWidth = 3.dp ) } } }

