                    placeholder = when (field.type) {
                        FieldType.DROPDOWN -> field.options.joinToString(" / ")
                        else -> field.placeHolderEn
                    },
                    singleLine = field.type != FieldType.TEXTAREA,
                    lines = if (field.type == FieldType.TEXTAREA) 4 else 1
